/** کوتاه‌نویس برای تعریف امکان */
function mb_f($id, $cat, $section, $title, $tip, $x = []) {
    return array_merge(['id' => $id, 'cat' => $cat, 'section' => $section, 'title' => $title, 'tip' => $tip], $x);
}
function mb_req($file, $label) { return ['plugin' => $file, 'label' => $label]; }

/** گزینه‌های پویا */
function mb_post_type_options() {
    $out = [];
    foreach (get_post_types(['public' => true], 'objects') as $pt) {
        $out[$pt->name] = $pt->labels->singular_name ?: $pt->name;
    }
    return $out;
}
function mb_widget_options() {
    return [
        'WP_Widget_Pages' => 'برگه‌ها', 'WP_Widget_Calendar' => 'تقویم', 'WP_Widget_Archives' => 'بایگانی',
        'WP_Widget_Links' => 'پیوندها', 'WP_Widget_Media_Audio' => 'صوت', 'WP_Widget_Media_Image' => 'تصویر',
        'WP_Widget_Media_Gallery' => 'گالری', 'WP_Widget_Media_Video' => 'ویدیو', 'WP_Widget_Meta' => 'متا',
        'WP_Widget_Search' => 'جستجو', 'WP_Widget_Text' => 'متن', 'WP_Widget_Categories' => 'دسته‌ها',
        'WP_Widget_Recent_Posts' => 'نوشته‌های اخیر', 'WP_Widget_Recent_Comments' => 'دیدگاه‌های اخیر',
        'WP_Widget_RSS' => 'RSS', 'WP_Widget_Tag_Cloud' => 'ابر برچسب‌ها', 'WP_Nav_Menu_Widget' => 'منوی ناوبری',
